// Minimal indexing sketch (pseudo)
function indexDocs(docs) {
  const idx = {};
  for (const d of docs) {
    for (const t of tokenize(d.text)) {
      if (!idx[t]) idx[t] = [];
      idx[t].push(d.id);
    }
  }
  return idx;
}
```

